import React from 'react';

function News({ lang }) {
  return (
    <div>
      <h1>{lang === 'ru' ? 'Отличная новость.' : 'Great news.'}</h1>
      <p>{lang === 'ru' ? 'Уже тепло!' : 'It is warm already!'}</p>
    </div>
  );
}

export default News;
